import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

/**
 * Acceptance Artifact: union-acceptance/linux-socket-territory-observation-capcell-fabrication.test.mjs
 * Objective: Observe Linux socket territory via /proc/net and ss-style input without mutation.
 */

// Target namespace import (Expected to exist as a local module)
import * as ObservationCapCell from './linux-socket-territory-observation-capcell-fabrication.mjs';

test('exact-loopback-tcp-territory', () => {
    // GIVEN: Injected snapshot
    const mockProcNetTcp = [
        "sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode",
        " 0: 0100007F:0050 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 12345 1 00000000ffff8880 20 4 2 10 -1",
    ].join('\n');

    // WHEN: Observation is invoked with policy
    const policy = { admissibleDenominator: "100" };
    const result = ObservationCapCell.observeLinuxSocketTerritory({
        snapshot: { tcp: mockProcNetTcp },
        policy
    });

    // THEN: Assertion of typed capacity/occupancy
    assert.strictEqual(typeof result.capacity, 'object');
    assert.strictEqual(result.occupancy.numerator, "1");
    assert.strictEqual(result.occupancy.denominator, "100");
    assert.strictEqual(result.available.numerator, "99");
    assert.strictEqual(result.available.denominator, "100");

    // Forbidden check: No floats
    assert.match(result.occupancy.numerator, /^\d+$/);
    assert.strictEqual(result.share.numerator, "1");
    assert.strictEqual(result.share.denominator, "100");
});

test('typed-observation-refusal', () => {
    // GIVEN: Unobservable state
    const badState = { snapshot: null };

    // WHEN: Operation invoked
    const result = ObservationCapCell.observeLinuxSocketTerritory(badState);

    // THEN: Typed refusal
    assert.strictEqual(result.status, 'REFUSAL');
    assert.ok(result.reason.includes('missing observation'));
    // Forbidden: No zero measurement
    assert.notStrictEqual(result.measurement, 0);
});

// Cleanup lifecycle
const tmp = mkdtempSync(join(tmpdir(), 'cap-test-'));
try {
    // Run tests
} finally {
    rmSync(tmp, { recursive: true, force: true });
}
